import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t,a}from"./chunks/qr_libre2direct-calib-30.qmCsLi9X.js";import{_ as i,o as s,c as o,a3 as l}from"./chunks/framework.g9mfNVRQ.js";const g=JSON.parse('{"title":"Libre 2 Direct","description":"","frontmatter":{"source_hash":"03b49989fb","source_commit":"e9ebf28"},"headers":[],"relativePath":"fr/install/libre2.md","filePath":"fr/install/libre2.md"}'),n={name:"fr/install/libre2.md"};function u(c,r,p,d,m,h){return s(),o("div",null,[...r[0]||(r[0]=[l('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Libre Bluetooth</p></div><h3 id="libre-2-direct" tabindex="-1">Libre 2 Direct <a class="header-anchor" href="#libre-2-direct" aria-label="Permalink to &quot;Libre 2 Direct {#libre-2-direct}&quot;">​</a></h3><p>Cette page explique comment activer la connexion Bluetooth directe entre le capteur et xDrip, sans transmetteur.</p><h4 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h4><p>Le téléphone sur lequel vous avez installé xDrip possède un lecteur NFC.</p><p>Si l&#39;application du fabricant est installée sur le téléphone que vous utilisez pour xDrip, <strong>vous l&#39;avez désinstallée</strong>.<br> Si elle est installée sur un autre téléphone ou si vous utilisez le lecteur Bluetooth, vous avez éloigné ces appareils ou les avez isolés pour qu&#39;ils ne causent pas d&#39;interférences.</p><h4 id="setting-up-for-the-first-time" tabindex="-1">Première configuration <a class="header-anchor" href="#setting-up-for-the-first-time" aria-label="Permalink to &quot;Première configuration {#setting-up-for-the-first-time}&quot;">​</a></h4><p>(Cliquez sur <a href="#starting-libre-2-sensors">Démarrer le capteur</a> pour les capteurs suivants).</p><div class="info custom-block"><p class="custom-block-title">Seuls les modèles de capteurs Libre 2/2+ Europe sont pris en charge</p><p>Vous devez installer la <a href="./../use/OOP.html#oop2">dernière application OOP2</a>.</p></div><p>La documentation de référence du Libre 2 se trouve <a href="https://www.minimallooper.com/post/how-to-setup-freestyle-libre-2-and-oop2-to-use-a-native-bluetooth-connection-in-xdrip" target="_blank" rel="noreferrer">ici</a> mais elle n&#39;est plus à jour.</p><br><div class="warning custom-block"><p class="custom-block-title">Attention</p><p><strong>Désinstallez toute application connectée au capteur et isolez le lecteur avant d&#39;essayer de vous connecter à xDrip.</strong><br> Si vous connectez votre capteur directement à xDrip, vous perdrez définitivement les alarmes de l&#39;application du fabricant ou du lecteur, sans possibilité de les récupérer.<br> Si vous n&#39;êtes pas sûr que cela fonctionnera, testez le système avec un capteur en fin de vie.<br> Comme avec les transmetteurs Libre, le succès et la fiabilité varient selon votre téléphone.<br> Associer votre capteur à xDrip annule la garantie du fabricant sur la fonction Bluetooth du capteur.</p></div><h4 id="setup-xdrip" tabindex="-1">Configurer xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurer xDrip {#setup-xdrip}&quot;">​</a></h4><p>Pour aller plus vite, vous pouvez scanner le QR code ci-dessous pour charger les paramètres nécessaires au Libre 2/2+ direct avec la fonction <a href="./../use/copysettings.html#auto-configure">Configuration automatique</a> de xDrip. Si vous consultez la documentation depuis le téléphone sur lequel vous installez xDrip, enregistrez d&#39;abord les images, puis chargez-les avec la fonction « Fichier image » de la configuration automatique.</p><p>Ils règlent <strong>la <a href="./../use/misc.html#oop2">calibration sur désactivée</a>, recommandé pour une première utilisation</strong>. Si vous voulez au contraire étalonner, <a href="./libre2direct-calib.html">suivez ceci</a>. La liste complète des paramètres importés est présentée <a href="./libre2direct-qr-settings.html">ici</a>.</p><p>QR codes - Cliquez sur l&#39;image pour l&#39;agrandir</p><table tabindex="0"><thead><tr><th style="text-align:center;">Sans étalonnage</th><th style="text-align:center;">Avec étalonnage</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./libre2direct-qr-settings.html"><img src="'+t+'" style="zoom:50%;"></a></td><td style="text-align:center;"><a href="./libre2direct-calib.html"><img src="'+a+'" style="zoom:50%;"></a></td></tr></tbody></table><p>Si vous avez utilisé les QR codes, vous pouvez passer directement à <a href="#starting-libre-2-sensors">Démarrer les capteurs Libre 2</a></p><h4 id="configure-nfc" tabindex="-1">Configurer le NFC <a class="header-anchor" href="#configure-nfc" aria-label="Permalink to &quot;Configurer le NFC {#configure-nfc}&quot;">​</a></h4><p>Configurez le NFC exactement <a href="./../use/NFC.html">comme ceci</a>.</p><h4 id="starting-libre-2-sensors" tabindex="-1">Démarrer les capteurs Libre 2 <a class="header-anchor" href="#starting-libre-2-sensors" aria-label="Permalink to &quot;Démarrer les capteurs Libre 2 {#starting-libre-2-sensors}&quot;">​</a></h4><p>Posez physiquement votre capteur Libre 2/2+ et démarrez-le avec le lecteur ou avec LibreLink. Notez l&#39;heure à laquelle le capteur sera prêt. Si vous utilisez le même téléphone que xDrip, désactivez LibreLink sur le téléphone. Vous devriez voir des valeurs de glycémie en le scannant. Attendez maintenant 60 minutes que le capteur ait terminé son préchauffage et son auto-étalonnage.</p><h4 id="connect-to-the-sensor" tabindex="-1">Se connecter au capteur <a class="header-anchor" href="#connect-to-the-sensor" aria-label="Permalink to &quot;Se connecter au capteur {#connect-to-the-sensor}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Arrêter le capteur</p></div><p>Si un capteur précédent est connecté à xDrip, arrêtez l&#39;ancien capteur.</p><p>Scannez le capteur avec le NFC de xDrip et vérifiez que les messages « Scan en cours » puis « Scan OK ! » s&#39;affichent.</p><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Tenez le téléphone immobile pendant le scan du capteur et ne le bougez pas : c&#39;est plus long que la lecture habituelle avec l&#39;application du fabricant.<br> N&#39;oubliez pas d&#39;attendre une minute entre deux scans NFC successifs.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Démarrer le capteur</p></div><p>Démarrez le capteur dans xDrip. Lorsqu&#39;on vous demande l&#39;heure à laquelle vous avez physiquement démarré le capteur, n&#39;indiquez pas une heure antérieure à la réalité pour éviter des valeurs incohérentes.</p><p>Attendez 60 secondes et scannez à nouveau avec xDrip. Cela ajoute le capteur comme appareil Bluetooth dont xDrip recevra les valeurs. Vous devriez voir la notification NOUVEAU CAPTEUR DÉMARRÉ. Si vous avez choisi « No calibration », vous devriez voir la première valeur immédiatement. Si vous avez choisi l&#39;étalonnage, vous devriez alors être sur l&#39;écran « Collecte des premières lectures ». Vous devrez alors attendre entre 3 et 15 minutes que 3 valeurs soient reçues, puis la demande <strong>Calibrer le capteur?</strong> s&#39;affichera, sauf si vous avez sélectionné « No calibration » dans les <a href="./../use/misc.html#oop2">paramètres OOP2</a>. Après la saisie de l&#39;étalonnage, le capteur Libre 2/2+ devrait être associé à xDrip et fournir des valeurs toutes les 5 minutes.</p><p>Vous pouvez vérifier que tout fonctionne en comparant avec « Ce à quoi cela devrait ressembler » <a href="./../troubleshoot/libre2direct.html#what-it-should-look-like">ici</a></p><p>Si vous avez du mal à obtenir les données directement du capteur, scannez-le toutes les 5 minutes avec le NFC de xDrip jusqu&#39;à la demande d&#39;étalonnage (si vous avez choisi l&#39;<a href="./../use/misc.html#oop2">option d&#39;étalonnage</a> avec OOP2).</p><br><h4 id="problems" tabindex="-1"><strong>Des problèmes ?</strong> <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;**Des problèmes ?** {#problems}&quot;">​</a></h4><p>Consultez la page de <a href="./../troubleshoot/libre2direct.html">dépannage</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 7/12/2024</em></a></p>',37)])])}const z=i(n,[["render",u]]);export{g as __pageData,z as default};
